    r"(?:摄像头|相机|镜头).{0,12}(?:一直开|自动开|开着|开了|打开|打开了|开没|有没有开|是否开|是不是开|自动拍|偷拍|拍我|拍人|识别|人脸|表情|情绪|隐私|关着|关了|关闭|关掉|关上|关没|有没有关|是否关|是不是关)|"
    r"(?:麦克风|话筒|语音).{0,12}(?:一直开|自动开|开着|开了|打开|打开了|开没|有没有开|是否开|是不是开|偷听|录音|录我|监听|保存|上传|保留|留存|留下|传出去|发出去|隐私|关着|关了|关闭|关掉|关上|关没|有没有关|是否关|是不是关))",
