def fetch_json(path, timeout=4):
    with urllib.request.urlopen(f"{API_BASE}{path}", timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def post_json(path, payload, timeout=4):
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        f"{API_BASE}{path}",
        data=body,
        headers={"content-type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        response.read()


def post_json_result(path, payload, timeout=4):
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(
        f"{API_BASE}{path}",
        data=body,
        headers={"content-type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def claim_commands(min_age_ms=CLAIM_AFTER_MS, source=""):
    params = {
        "claim": "1",
        "client": CLIENT_ID,
        "minAgeMs": str(min_age_ms),
        "accept": "pi",  # 声明可认领 target=pi 的定向命令（如手机端宠物按钮）
    }
    if source:
        params["source"] = source
    query = urllib.parse.urlencode(params)
    return fetch_json(f"/api/pi-control?{query}").get("commands", [])


