MEDIA_WORD_PATTERN = r"(?:歌|音乐|声音|配乐|bgm)"
QUALIFIED_NEXT_PLAYLIST_PATTERN = (
    rf"(?:换一?首|换首)(?!\s*{MEDIA_WORD_PATTERN}).{{1,18}}{MEDIA_WORD_PATTERN}|"
    rf"(?:换一?首|换首).{{0,8}}(?:不吵|别太吵|安静(?:点|一点)?|柔和(?:点|一点)?|稳(?:一点)?|"
    rf"不慌|别慌|不抢注意力|不那么上头|不上头|适合(?:通勤|开车|自驾|散步|写代码|工作|学习|睡前|夜路|回家路上|下班路上)|"
    rf"雨天|雨夜|睡前|通勤|回家路上|下班路上|上班路上|路上|开车|自驾|散步|湖边|水边|海边|写代码|工作|学习)(?:的)?{MEDIA_WORD_PATTERN}?"
)

OPEN_PLAYLIST_RE = re.compile(
    r"(想听|听点|来点|放点|播点|来一?首.*(歌|音乐|声音|配乐|bgm)|播放.*(音乐|歌曲|歌)|推荐.*歌|安排.*歌|"
    r"给我.*(歌|音乐|声音|配乐|bgm)|帮我.*(挑|选|找|排).*(歌|音乐|声音|配乐|bgm)|"
    r"(挑|选)几首.*(歌|音乐|声音|配乐|bgm)|找.*(歌|音乐|声音|配乐|bgm)|"
    r"(?:今天|今晚|这趟|这条|电台|日落).{0,12}(?:歌|歌曲|歌单|曲目).{0,8}(?:怎么排|咋排|怎么安排|咋安排|怎么走|咋走|顺序|安排|怎么播|怎么放)|"
    r"(不吵|别太吵).{0,8}(歌|音乐|声音|配乐|bgm)|"
    r"(?:安静(?:点|一点)?|柔和(?:点|一点)?|轻(?:点|一点)?|慢(?:点|一点)?|稳一点|小声(?:点|一点)?|低声(?:点|一点)?|轻声(?:点|一点)?|压低(?:点|一点)?).{0,8}(歌|音乐|声音|配乐|bgm)|"
    r"(?:来一?首|播放).{0,8}(不吵|别太吵|安静(?:点|一点)?|柔和(?:点|一点)?|稳一点)(?:的)?(?:歌|音乐|声音|配乐|bgm)?|"
    rf"{QUALIFIED_NEXT_PLAYLIST_PATTERN}|"
    r"来一(点|段).*(歌|音乐|声音|配乐|bgm)|放一段|播一段|"
    r"歌单|配乐|背景音乐|适合.*听|听什么|音乐|歌曲|"
    r"chill|playlist|music|songs?|bgm)",
    re.I,
)

QUALIFIED_NEXT_PLAYLIST_RE = re.compile(QUALIFIED_NEXT_PLAYLIST_PATTERN, re.I)
SCENE_PLAYLIST_PRIORITY_RE = re.compile(
    r"(?:雨天|雨夜|通勤|散步|外面散步|回家路上|睡前|压力|焦虑|工作|学习).{0,14}"
    r"(?:来点|来首|听点|想听|放点|播点|歌|音乐|不吵|别太吵|慢|柔和|轻|稳|不抢注意力)|"
    r"(?:来点|来首|来一首|放点|播点|想听).{0,12}"
    r"(?:不吵|别太吵|安静|柔和|稳一点|轻一点|慢一点|慢的|轻的|歌|音乐)|"
    r"(?:不吵|别太吵|安静(?:点|一点)?|柔和(?:点|一点)?|轻(?:点|一点)?|慢(?:点|一点)?|稳一点|小声(?:点|一点)?|低声(?:点|一点)?|轻声(?:点|一点)?|压低(?:点|一点)?).{0,8}"
    rf"{MEDIA_WORD_PATTERN}",
    re.I,
)


def scene_hint_matches(text, norm_text, words):
    raw = str(text or "").lower()
    for word in words:
        raw_word = str(word or "").lower()
        norm_word = normalize(word)
        if (raw_word and raw_word in raw) or (norm_word and norm_word in norm_text):
            return True
    return False


def scene_word_matches_track(word, hay, hay_norm):
    raw_word = str(word or "").lower()
    norm_word = normalize(word)
    return (raw_word and raw_word in hay) or (norm_word and norm_word in hay_norm)


def candidate_tracks(text, limit=AGENT_MAX_CANDIDATES):
    hit_city = match_city(text)
    if hit_city:
        return hit_city.get("tracks", [])[:limit]

    tokens = query_tokens(text)
    norm_text = normalize(text)
    scored = []
    for track in all_tracks():
        city_text = f"{track.get('cityNameZh')} {track.get('cityName')} {track.get('citySlug')}"
        hay = f"{city_text} {track.get('title')} {track.get('artist')} {track.get('introText')}".lower()
        hay_norm = normalize(hay)
        score = 0
        for token in tokens:
            if len(token) >= 2 and token in hay_norm:
                score += 2
            elif len(token) >= 3 and token in hay:
                score += 2
        for trigger, words in SCENE_HINTS.items():
            if trigger in norm_text or scene_hint_matches(text, norm_text, words):
                score += sum(3 for word in words if scene_word_matches_track(word, hay, hay_norm))
        if score:
            scored.append((score, track))

    scored.sort(key=lambda item: (-item[0], item[1].get("cityNameZh", ""), item[1].get("title", "")))
    tracks = [track for _, track in scored[:limit]]
    if tracks:
        return tracks

    fallback = []
    for city in ordered_cities():
        fallback.extend((city.get("tracks") or [])[:2])
        if len(fallback) >= limit:
            break
    return fallback[:limit]


def compact_intro(track, limit=96):
    text = re.sub(r"\s+", " ", track.get("introText") or "").strip()
    return text[:limit]


def agent_payload(text):
    cities = [
        {
            "slug": city.get("slug"),
            "cityNameZh": city.get("cityNameZh"),
            "cityName": city.get("cityName"),
        }
        for city in catalog
    ]
    candidates = [
        {
            "id": track_key(track),
            "title": track.get("title"),
            "artist": track.get("artist"),
            "citySlug": track.get("citySlug"),
            "cityNameZh": track.get("cityNameZh"),
            "intro": compact_intro(track),
        }
        for track in candidate_tracks(text)
    ]
    current = {}
    if playlist and current_index >= 0:
        track = playlist[current_index % len(playlist)]
        current = {
            "citySlug": track.get("citySlug"),
            "cityNameZh": track.get("cityNameZh"),
            "track": track.get("title"),
            "artist": track.get("artist"),
        }
    return {
        "userText": text,
        "current": current,
        "cities": cities,
        "candidates": candidates,
    }


AGENT_SYSTEM = """你是 Sunset Radio 树莓派端的语音意图代理。
你的任务是把用户的自然语言变成一个安全的电台动作，只输出 JSON。
允许的 action：
- switch_city：用户想听某座城市/某地音乐。必须返回已有 cities 里的 slug。
- set_playlist：用户描述心情、风格、场景、地域或开放点歌。必须只返回 candidates 里的 id，3-8 首。
- day_program：用户要 24 小时/全天/一整晚/生成一档电台。
- next_track、prev_track、pause、play：明确播放控制。
- status、help：设备状态或帮助。
- none：不是电台控制，或无法判断。
不要编造城市、歌曲或 id。用户提到城市时优先 switch_city；用户说“海边/夜晚/电子/爵士/想听一点...”这类开放请求时优先 set_playlist。
JSON 形状：{"action":"...", "slug":"", "trackIds":[], "reply":"一句中文电台口吻回执"}"""


def parse_json_text(text):
    raw = str(text or "").strip()
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", raw, re.S)
        if not match:
            return {}
        try:
            return json.loads(match.group(0))
        except json.JSONDecodeError:
            return {}


def cloud_agent_decision(text):
    if not NATIVE_AGENT:
        return {}
    prompt = json.dumps(agent_payload(text), ensure_ascii=False)
    frost_payloads = [
        {"system": AGENT_SYSTEM, "prompt": prompt, "json": True},
        {"system": AGENT_SYSTEM, "prompt": prompt, "json": False},
        {"prompt": f"{AGENT_SYSTEM}\n\n输入：{prompt}", "json": False},
    ]
    for payload in frost_payloads:
        try:
            result = post_json_result("/api/frost-llm", payload, timeout=AGENT_TIMEOUT)
        except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, json.JSONDecodeError, OSError):
            continue
        decision = parse_json_text(result.get("text"))
        if decision:
            return decision
    edge_payload = {
        "task": "chat",
        "system": AGENT_SYSTEM,
        "prompt": prompt,
        "json": True,
    }
    try:
        result = post_json_result("/api/edge", edge_payload, timeout=AGENT_TIMEOUT)
    except (urllib.error.HTTPError, urllib.error.URLError, TimeoutError, json.JSONDecodeError, OSError):
        return {}
    if result.get("backend") == "stub":
        return {}
    return parse_json_text(result.get("text"))


def next_sunset_minutes(city):
    now = time.gmtime()
    utc_minutes = now.tm_hour * 60 + now.tm_min
    local_minutes = (utc_minutes + int(round(city.get("tzOffset", 0) * 60))) % 1440
    sunset_minutes = 18 * 60 + 20
    return (sunset_minutes - local_minutes) % 1440


def build_day_playlist():
    out = []
    for city in sorted(catalog, key=next_sunset_minutes):
        out.extend(city["tracks"][: max(1, min(2, len(city["tracks"])))])
    return out


def ordered_cities():
    return sorted(catalog, key=next_sunset_minutes)


def current_city_slug():
    if playlist and current_index >= 0:
        track = playlist[current_index % len(playlist)]
        slug = track.get("citySlug") or ""
        if slug:
            return slug
        track_city = str(track.get("cityNameZh") or track.get("cityName") or track.get("city") or "").strip()
        track_city_norm = normalize(track_city)
        track_city_lower = track_city.lower()
        for city in catalog:
            zh = normalize(city.get("cityNameZh") or city.get("nameZh") or "")
            name = str(city.get("cityName") or city.get("name") or "").strip().lower()
            if (track_city_norm and track_city_norm == zh) or (track_city_lower and track_city_lower == name):
                return city.get("slug") or ""
    return ""


def hop_city(step=1):
    cities = ordered_cities()
    if not cities:
        publish_state(
            status="idle",
            label="静音中" if MUTE else "No cities",
            city="Sunset Radio",
            track="",
            message="静音中：音乐DJ 还在等城市歌单。" if MUTE else "音乐DJ 还在等城市歌单。",
        )
        return
    slug = current_city_slug()
    index = next((i for i, city in enumerate(cities) if city.get("slug") == slug), -1)
    target = cities[(index + step) % len(cities)] if index >= 0 else cities[0]
    switch_city(target)


def city_relative_to_current(step=1):
    cities = ordered_cities()
    if not cities:
        return None
    slug = current_city_slug()
    index = next((i for i, city in enumerate(cities) if city.get("slug") == slug), -1)
    return cities[(index + step) % len(cities)] if index >= 0 else cities[0]


def next_city_after_current():
    return city_relative_to_current(1)


def previous_city_before_current():
    return city_relative_to_current(-1)


def upcoming_cities(limit=3):
    cities = ordered_cities()
    if not cities:
        return []
    slug = current_city_slug()
    index = next((i for i, city in enumerate(cities) if city.get("slug") == slug), -1)
    start = index + 1 if index >= 0 else 0
    return [cities[(start + offset) % len(cities)] for offset in range(min(limit, len(cities)))]


def format_wait(minutes):
    minutes = max(0, int(minutes))
    if minutes < 60:
        return f"{minutes}分钟"
    hours = minutes // 60
    rest = minutes % 60
    return f"{hours}小时{rest}分" if rest else f"{hours}小时"


def stop_player():
    global player
    if player and player.poll() is None:
        player.terminate()
        try:
            player.wait(timeout=2)
        except subprocess.TimeoutExpired:
            player.kill()
    player = None


def player_active():
    return bool(player and player.poll() is None)


def player_command(url):
    ffplay = shutil.which("ffplay")
    if ffplay:
        return [
            ffplay,
            "-nodisp",
            "-autoexit",
            "-loglevel",
            "error",
            "-volume",
            PLAYER_VOLUME,
            url,
        ]
    cvlc = shutil.which("cvlc")
    if cvlc:
        return [cvlc, "--intf", "dummy", "--play-and-exit", "--quiet", url]
    return []


def ensure_radio_audio_output():
    wpctl = shutil.which("wpctl")
    if not wpctl:
        return
    volume = os.environ.get("SUNSET_RADIO_VOLUME", os.environ.get("SUNSET_PLAYER_VOLUME", "45"))
    subprocess.run([wpctl, "set-mute", "@DEFAULT_AUDIO_SINK@", "0"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
    subprocess.run(
        [wpctl, "set-volume", "@DEFAULT_AUDIO_SINK@", f"{volume}%"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )


def trigger_wifi_failover_from_button():
    if not WIFI_FAILOVER_ON_BUTTON:
        return False
    script = os.path.join(os.path.dirname(os.path.abspath(__file__)), "wifi_failover.py")
    if not os.path.exists(script):
        return False
    env = os.environ.copy()
    for key, value in {
        "SUNSET_WIFI_CURRENT_TIMEOUT": "3",
        "SUNSET_WIFI_SCAN_TIMEOUT": "6",
        "SUNSET_WIFI_SHOW_TIMEOUT": "3",
        "SUNSET_WIFI_ADD_TIMEOUT": "5",
        "SUNSET_WIFI_MODIFY_TIMEOUT": "5",
        "SUNSET_WIFI_CONNECT_TIMEOUT": "7",
        "SUNSET_WIFI_FALLBACK_TIMEOUT": "5",
    }.items():
        env.setdefault(key, value)
    try:
        timeout = max(8, int(env.get("SUNSET_WIFI_BUTTON_TIMEOUT", "24") or 24))
    except ValueError:
        timeout = 24
    try:
        result = subprocess.run(
            [sys.executable or "/usr/bin/python3", script, "--json"],
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=timeout,
            env=env,
        )
        try:
            report = json.loads(result.stdout or "{}")
        except json.JSONDecodeError:
            report = {}
        message = report.get("message") if isinstance(report, dict) else ""
        if message:
            publish_state(
                status="idle",
                label="设备状态",
                city="网络",
                track=report.get("selected") or "手机热点",
                message=message,
            )
        return result.returncode == 0 and (not isinstance(report, dict) or report.get("ok") is not False)
    except (OSError, subprocess.TimeoutExpired):
        publish_state(
            status="idle",
            label="设备状态",
            city="网络",
            track="手机热点",
            message="手机热点切换超时；先继续播放，系统会保留已保存 Wi-Fi 自动重连。",
        )
        return False


def parse_wpctl_volume(text):
    match = re.search(r"Volume:\s*([0-9.]+)", str(text or ""))
    if not match:
        return None
    try:
        return max(0, min(100, int(round(float(match.group(1)) * 100))))
    except (TypeError, ValueError):
        return None


def read_output_volume(wpctl=None):
    wpctl = wpctl or shutil.which("wpctl")
    if not wpctl:
        return None
    result = subprocess.run(
        [wpctl, "get-volume", "@DEFAULT_AUDIO_SINK@"],
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    return parse_wpctl_volume(result.stdout)


def save_volume_overlay(volume, direction):
    if volume is None:
        return False
    try:
        os.makedirs(os.path.dirname(VOLUME_STATE_PATH) or ".", exist_ok=True)
        with open(VOLUME_STATE_PATH, "w", encoding="utf-8") as handle:
            json.dump(
                {"volume": max(0, min(100, int(volume))), "dir": "down" if direction == "down" else "up", "ts": time.time()},
                handle,
                ensure_ascii=False,
            )
            handle.write("\n")
        return True
    except (OSError, TypeError, ValueError):
        return False


def adjust_radio_volume(direction):
    state = load_audio_mode()
    if not audio_allows_music(state):
        publish_state(
            status="idle",
            label="静音中" if state.get("mode") in {"hard_mute", "soft_mute"} else "对话待命",
            city="声音入口",
            track=state["label"],
            message=f"{state['label']}：我不会在这个模式里调响电台音量。",
        )
        return False
    wpctl = shutil.which("wpctl")
    if not wpctl:
        publish_state(
            status="idle",
            label="设备状态",
            city="声音入口",
            track="音量",
            message="音乐DJ 找不到系统音量控制。",
        )
        return False
    direction = "down" if direction == "down" else "up"
    if direction == "up":
        subprocess.run([wpctl, "set-mute", "@DEFAULT_AUDIO_SINK@", "0"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
    subprocess.run(
        [wpctl, "set-volume", "-l", "1.0", "@DEFAULT_AUDIO_SINK@", f"{VOLUME_STEP}%{'-' if direction == 'down' else '+'}"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    volume = read_output_volume(wpctl)
    save_volume_overlay(volume, direction)
    if volume is None:
        message = "音量已调低一点。" if direction == "down" else "音量已调高一点。"
    else:
        message = f"音量已调{'低' if direction == 'down' else '高'}到约 {volume}%。"
    publish_state(
        status="idle",
        label="设备状态",
        city="声音入口",
        track="音量",
        message=message,
    )
    return True


def play_track(index):
    global current_index, player
    if not playlist:
        publish_state(
            status="idle",
            label="No songs",
            city="Sunset Radio",
            track="",
            message="音乐DJ 正在等一份可播放歌单。",
        )
        return
    current_index = index % len(playlist)
    track = playlist[current_index]
    stop_player()
    open_radio_mode("music playback command")
    save_whisplay_media(track)
    if MUTE:
        publish_state(
            status="idle",
            label="静音中",
            city=track["cityNameZh"],
            track=track["title"],
            message=f"静音中：{track['artist']} - {track['title']}",
        )
        return
    cmd = player_command(track["audioUrl"])
    publish_state(
        status="playing",
        label="Now playing",
        city=track["cityNameZh"],
        track=track["title"],
        message=f"{track['artist']} - {track['title']}",
    )
    if not cmd:
        publish_state(
            status="idle",
            label="需要播放器",
            city=track["cityNameZh"],
            track=track["title"],
            message="音乐DJ 找不到播放器。",
        )
        return
    player = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def play_next(step=1):
    global playlist
    if not playlist:
        playlist = build_day_playlist()
    play_track(current_index + step if current_index >= 0 else 0)


def toggle_audio_from_button():
    global current_index, playlist
    state = load_audio_mode()
    if audio_allows_music(state) and player_active():
        stop_player()
        publish_audio_mode(
            "soft_mute",
            reason="orange long press",
            message="已关闭：电台静音待命；长按橙色键会重新尝试热点并播放当前日落城市。",
        )
        return
    publish_audio_mode(
        "radio",
        reason="orange long press",
        ttl=AUDIO_RADIO_TTL_SEC,
        message="已打开：先尝试手机热点，播放当前日落城市；再长按橙色键关闭。",
    )
    trigger_wifi_failover_from_button()
    ensure_radio_audio_output()
    playlist = build_day_playlist()
    current_index = -1
    play_next(0)


def start_radio_playback(reason="user start playback"):
    global playlist
    if is_hard_mute(load_audio_mode()):
        publish_state(
            status="idle",
            label="静音中",
            city="声音入口",
            track="硬静音",
            message="硬静音中：不会自动开始播放。长按橙色键或说“解除静音”后再打开电台。",
        )
        return False
    publish_audio_mode(
        "radio",
        reason=reason,
        ttl=AUDIO_RADIO_TTL_SEC,
        message="电台声音已打开，开始播放当前日落城市。",
    )
    ensure_radio_audio_output()
    if not playlist:
        playlist = build_day_playlist()
    play_next(0 if current_index >= 0 else 1)
    return True


def switch_city(city):
    global playlist
    playlist = city["tracks"][:]
    play_track(0)


def set_playlist_tracks(tracks, reply=""):
    global playlist
    clean = [track for track in tracks if track and track.get("audioUrl")]
    if not clean:
        return False
    playlist = clean
    play_track(0)
    if reply and playlist and current_index >= 0:
        track = playlist[current_index % len(playlist)]
        publish_state(
            status="idle" if MUTE else "playing",
            label="静音中" if MUTE else "DJ playlist",
            city=track.get("cityNameZh") or "Sunset Radio",
            track=track.get("title") or "",
            message=(
                f"静音中：{reply} · {track.get('artist')} - {track.get('title')}"
                if MUTE
                else f"{reply} · {track.get('artist')} - {track.get('title')}"
            ),
        )
    return True


def start_day_radio():
    global playlist
    playlist = build_day_playlist()
    play_track(0)
    if MUTE:
        return
    publish_state(
        status="playing",
        label="24H radio",
        city=playlist[current_index]["cityNameZh"] if playlist else "Sunset Radio",
        track=playlist[current_index]["title"] if playlist else "",
        message="音乐DJ 已经接上全天日落顺序。",
    )


def build_planned_playlist(schedule):
    """Turn the day-planner schedule (real-sunset ordered) into a playable track list.

    Prefers the planner's mood-chosen ``trackKeys`` per stop; if a stop has none (or they
    do not resolve), falls back to the city's first ``trackCount`` tracks. Always degrades
    to whatever the catalog can supply.
    """
    by_slug = {city.get("slug"): city for city in catalog if city.get("slug")}
    by_name = {city.get("cityNameZh"): city for city in catalog if city.get("cityNameZh")}
    out = []
    for stop in schedule or []:
        city = by_slug.get(stop.get("slug")) or by_name.get(stop.get("cityNameZh"))
        if not city:
            continue
        tracks = city.get("tracks") or []
        chosen = []
        for key in stop.get("trackKeys") or []:
            track = track_by_key(key)
            if track:
                chosen.append(track)
        if not chosen:
            count = max(1, min(int(stop.get("trackCount") or 1), len(tracks))) if tracks else 0
            chosen = tracks[:count]
        out.extend(chosen)
    return out


def publish_day_plan(capture=False):
    """Run the environment-perceiving day planner (live to /api/pi-plan), then play it.

    The planner narrates perceive → locate → weather → sunset → compose → commit to the
    web timeline; here we take its real-sunset-ordered schedule and start the radio from
    it. Any failure degrades to the deterministic static 24H order so a request never dies.
    """
    try:
        plan = sunset_day_planner.run_day_plan(catalog=catalog, capture=bool(capture))
    except Exception:
        start_day_radio()
        return

    schedule = plan.get("schedule") or []
    planned = build_planned_playlist(schedule)
    summary = plan.get("message") or "环境编排完成，接上全天日落顺序。"

    if planned:
        global playlist
        playlist = planned
        play_track(0)
    else:
        start_day_radio()

    if MUTE:
        # 静音只写屏：与全部 doctor/ambient 处理器同一约定，绝不在安静待命时出声。
        publish_state(
            status="idle",
            label="静音中",
            city="环境编排",
            track="全天日落节目单",
            message=f"静音中：{summary}",
        )
        return

    head = schedule[0] if schedule else {}
    publish_state(
        status="playing",
        label="环境编排",
        city=(playlist[current_index]["cityNameZh"] if playlist else head.get("cityNameZh") or "Sunset Radio"),
        track=(playlist[current_index]["title"] if playlist else ""),
        message=summary,
    )
    speak_text(summary)


# ---------------- 电子宠物：状态、心跳与神游 ----------------
# 宠物的「心」在 pet_state / pet_heartbeat（纯函数），这里只做接线：
# 采集输入（电量/光线记忆/本地日落）→ 跑一次心跳 → 执行动作 → 快照发到 /api/pi-pet。
# 隐私边界不变：心跳绝不拍照，只消费环境层已有的记忆。
PET = {"state": None, "tz": None, "location": None, "locationAt": 0.0, "homecoming": None}
PET_LOCATION_TTL = 600  # 位置配置基本不变，10 分钟刷新一次足够


def pet_now_ts():
    return int(time.time())


def _device_tz_offset():
    # 设备本地时区（小时）：宠物的作息按 Pi 自己的钟走。
    return -(time.altzone if time.daylight else time.timezone) / 3600.0


def pet_location():
    now = time.monotonic()
    if PET["location"] is not None and now - PET["locationAt"] < PET_LOCATION_TTL:
        return PET["location"]
    location = {}
    try:
        result = geo_skill.device_location()
        if result.get("ok"):
            location = result
    except Exception:
        location = {}
    PET["location"] = location
    PET["locationAt"] = now
    # 时区跟随位置刷新：用户中途「设置位置」后，宠物作息 10 分钟内跟上，不必重启。
    tz = location.get("tzOffset") if location else None
    PET["tz"] = float(tz) if tz is not None else _device_tz_offset()
    return location


def pet_tz():
    if PET["tz"] is None:
        pet_location()
    return PET["tz"]


def pet_home_sunset():
    """本地日落：距日落的**带符号**分钟数（刚过日落为负）+ 钟面。
    sunset_skill 的 minutesUntil 恒指向下一次日落（刚过就跳成 ~1438），这里换算回负值，
    否则「日落 ±15 分钟」出发窗只剩前一半，黄昏时段守护进程一重启当天神游就丢了。
    未配置位置返回 (None, "")，心跳退回 18:20 兜底。"""
    location = pet_location()
    if not location:
        return None, ""
    try:
        event = sunset_skill.next_sunset_event(
            {"cityNameZh": location.get("name") or "家", "lat": location.get("lat"), "lng": location.get("lng")},
            user_tz_offset=location.get("tzOffset"),
        )
        minutes = event.get("minutesUntil")
        if isinstance(minutes, (int, float)) and minutes >= 1440 - 60:
            minutes = minutes - 1440  # 昨天的日落刚过去几十分钟
        return minutes, event.get("userSunsetClock") or ""
    except Exception:
        return None, ""


def ensure_pet():
    if PET["state"] is not None:
        return PET["state"]
    state = pet_state.load_pet_state()
    now_ts = pet_now_ts()
    location = pet_location()
    _minutes, sunset_clock = pet_home_sunset()
    state, born = pet_state.ensure_born(
        state, now_ts, pet_tz(),
        city=(location.get("name") or "") if location else "",
        sunset_clock=sunset_clock,
    )
    if born:
        pet_state.save_pet_state(state)
    PET["state"] = state
    return state


def publish_pet_snapshot():
    state = ensure_pet()
    try:
        snapshot = pet_state.public_snapshot(state, pet_now_ts(), pet_tz())
        # 形态身份随心跳自愈：server 重启丢内存/某次变身 POST 失败后，手机端一分钟内自动对齐
        form = read_pet_form()
        if form:
            snapshot["form"] = form
        post_json("/api/pi-pet", snapshot)
    except Exception:
        pass


def pet_note_interaction(kind):
    state = ensure_pet()
    pet_state.note_interaction(state, kind, pet_now_ts(), pet_tz())
    pet_state.save_pet_state(state)


def choose_drift_destination():
    """挑「此刻正在日落的那座城」：黄金时刻进行中的优先，其次最快天黑的。"""
    try:
        events = sunset_skill.order_cities_by_sunset(catalog or [], user_tz_offset=pet_tz())
    except Exception:
        return {}
    pool = [e for e in events if e.get("hasCoords")] or events
    if not pool:
        return {}
    active = [e for e in pool if (e.get("goldenHour") or {}).get("active")]
    return (active or pool)[0]


def pet_start_drift():
    state = ensure_pet()
    if state.get("activity") == "dusk_drift":
        return state
    destination = choose_drift_destination()
    pet_state.begin_drift(state, destination, pet_now_ts(), pet_tz(), duration_min=PET_DRIFT_MIN)
    pet_state.save_pet_state(state)
    publish_pet_snapshot()
    return state


def _letter_llm(system, prompt):
    result = post_json_result(
        "/api/frost-llm", {"system": system, "prompt": prompt, "json": False}, timeout=AGENT_TIMEOUT + 4
    )
    return (result.get("text") or "").strip()


def _find_catalog_city(slug, name):
    for city in catalog or []:
        if (slug and city.get("slug") == slug) or (name and city.get("cityNameZh") == name):
            return city
    return None


def compose_drift_letter(drift, state):
    """组装归来信的上下文：目的地天气 + 按天气情绪选一首歌 + 家里今天的小事。
    每一步都可失败降级 —— 断网黄昏也要有信（letter_writer 的离线模板兜底）。"""
    drift = dict(drift or {})
    entry = _find_catalog_city(str(drift.get("slug") or ""), str(drift.get("cityNameZh") or ""))
    weather_line = ""
    mood_seed = {}
    sunset_clock = str(drift.get("sunsetClock") or "")
    if entry is not None:
        try:
            geo = geo_skill.city_geo(entry)
            if geo.get("ok"):
                report = weather_skill.observe_weather(geo.get("lat"), geo.get("lng"))
                if report.get("ok"):
                    weather_line = str(report.get("message") or "")
                    mood_seed = report.get("moodSeed") or {}
                    # 天气源带真实时区（含夏令时）的日落钟面，比静态时区表准 —— 信里统一用它，
                    # 避免同一封信里出现两个日落时刻。
                    if report.get("sunsetLocal"):
                        sunset_clock = str(report["sunsetLocal"])
        except Exception:
            pass
    track = {}
    if entry is not None:
        try:
            picks = track_select.select_tracks_for_mood(entry.get("tracks") or [], 1, mood_seed)
            if picks:
                track = {
                    "id": str(picks[0].get("id") or ""),
                    "title": str(picks[0].get("title") or ""),
                    "artist": str(picks[0].get("artist") or ""),
                    # DJ 稿：信正文直接用它（letter_writer 出信时把 introText 消费掉、不进落盘字段）
                    "introText": str(picks[0].get("introText") or ""),
                }
        except Exception:
            track = {}
    home_light = ""
    try:
        report = memory_report()
        if report.get("ok"):
            home_light = str((report.get("latest") or {}).get("light") or "")
    except Exception:
        home_light = ""
    now_ts = pet_now_ts()
    tz = pet_tz()
    context = {
        "no": int(state.get("lettersSent") or 0) + 1,
        "nowTs": now_ts,
        "atIso": f"{pet_state.local_date_str(now_ts, tz)}T{pet_state.local_clock_str(now_ts, tz)}",
        "daysAlive": pet_state.days_alive(state, now_ts, tz),
        "city": {
            "cityNameZh": drift.get("cityNameZh") or "",
            "slug": drift.get("slug") or "",
            "sunsetClock": sunset_clock,
        },
        "weatherLine": weather_line,
        "track": track,
        "homeEvents": list((state.get("today") or {}).get("events") or []),
        "homeLight": home_light,
    }
    return letter_writer.compose_letter(context, llm=_letter_llm)


def pet_end_drift():
    """神游归来 = 寄信到家：信先送进 /api/pi-inbox（落盘），寄成才计数。"""
    state = ensure_pet()
    drift = dict(state.get("drift") or {})
    letter = None
    try:
        letter = compose_drift_letter(drift, state)
    except Exception:
        letter = None
    state, city = pet_state.end_drift(state, pet_now_ts(), pet_tz())
    if letter:
        try:
            post_json("/api/pi-inbox", {"letter": letter})
            state["lettersSent"] = int(state.get("lettersSent") or 0) + 1
            state["lastLetterAt"] = str(letter.get("at") or "")
            pet_state.record_event(
                state, "letter", f"从{city}寄回第 {letter.get('no')} 封信", pet_now_ts(), pet_tz()
            )
        except Exception:
            letter = None  # 信箱不可达：这次不计数，明天的信还是第 no 封
    pet_state.save_pet_state(state)
    publish_pet_snapshot()
    return city, letter


def pet_tick_cycle():
    state = ensure_pet()
    now_ts = pet_now_ts()
    battery = None
    try:
        info = pisugar_battery_status()
        if info.get("available"):
            battery = info.get("capacity")
    except Exception:
        battery = None
    light = ""
    try:
        report = memory_report()
        if report.get("ok"):
            light = str((report.get("latest") or {}).get("light") or report.get("dominantLight") or "")
            if light == "unknown":
                light = ""
    except Exception:
        light = ""
    minutes, _clock = pet_home_sunset()
    state, actions = pet_heartbeat.tick(
        state,
        {
            "nowTs": now_ts,
            "tzOffset": pet_tz(),
            "localHour": pet_state.local_hour(now_ts, pet_tz()),
            "battery": battery,
            "light": light,
            "homeSunsetMinutes": minutes,
        },
    )
    if "start_drift" in actions:
        pet_start_drift()
        return
    if "end_drift" in actions:
        # 归来写信链路（目的地天气 HTTP + LLM + 两次 POST）最长可达 ~24s——
        # 放后台线程，绝不让黄昏时段的语音/按键命令等在单线程主循环后面。
        # in-flight 守卫防止 30s 后的下一次 tick 重复触发（activity 在信写完前仍是 dusk_drift）。
        homecoming = PET.get("homecoming")
        if homecoming is None or not homecoming.is_alive():
            thread = threading.Thread(target=pet_end_drift, daemon=True)
            PET["homecoming"] = thread
            thread.start()
        return
    pet_state.save_pet_state(state)
    publish_pet_snapshot()


