def publish_form_demo():
    """写一个 90 秒的演示窗标记，Whisplay 屏读到就开始三形态轮转——完全无声。"""
    try:
        os.makedirs(STATE_DIR, exist_ok=True)
        with open(os.path.join(STATE_DIR, "form-demo.json"), "w", encoding="utf-8") as handle:
            json.dump({"until": time.time() + 90}, handle)
    except OSError:
        pass
    _pet_reply("屏幕转起来了：90 秒形态演示，磁带盘和大圆脸都会来，不出声。")


PET_FORM_PATH = os.path.join(STATE_DIR, "pet-form.json")
PET_FORM_ORDER = ("avatar", "turntable", "face")
PET_FORM_REPLIES = {
    "avatar": "做回崽了：DJ 机器人待命。",
    "turntable": "变身唱片机：磁带盘和日落照片盘轮着转，唱臂已就位。",
    "face": "变身大圆脸：日落黄打底，眼皮半垂。",
}


def read_pet_form():
    """当前形态身份；没选过返回 ""=幼年未定型（屏上保持随机轮播）。"""
    try:
        with open(PET_FORM_PATH, "r", encoding="utf-8") as handle:
            value = str(json.load(handle).get("form") or "").strip()
        return value if value in PET_FORM_ORDER else ""
    except Exception:
        return ""


def publish_pet_form(form):
    """选定/切换形态身份：落盘给 Whisplay 屏读（1 秒内生效），同时推 /api/pi-pet
    让手机崽面板与 SUNSET-7 随身机同步锁定。"""
    try:
        os.makedirs(STATE_DIR, exist_ok=True)
        # tmp+replace 原子替换：Whisplay 1Hz 读端绝不会撞到半截 JSON（闪回幼年轮播一秒）
        tmp = PET_FORM_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump({"form": form, "updatedAt": time.time()}, handle)
        os.replace(tmp, PET_FORM_PATH)
    except OSError:
        pass
    try:
        post_json("/api/pi-pet", {"form": form})
    except Exception:
        pass
    _pet_reply(PET_FORM_REPLIES.get(form, f"形态已切到 {form}。"))


def publish_pet_form_cycle():
    """橙键三连击：崽 → 唱片机 → 大圆脸 → 崽 循环。没选过时从崽后面开始。"""
    current = read_pet_form() or "avatar"
    publish_pet_form(PET_FORM_ORDER[(PET_FORM_ORDER.index(current) + 1) % len(PET_FORM_ORDER)])


