def hotspot_status_message():
    status = collect_device_status()
    ip = status.get("ip") or ""
    report = collect_button_doctor()
    wifi = report.get("wifiFailover") or {}
    profiles = wifi.get("profiles") or []
    names = [str(item.get("ssid") or "").strip() for item in profiles if item.get("ssid")]
    prefix = ""
    if wifi.get("enabledOnLongPress"):
        if names:
            prefix = f"长按会先试手机热点：{' / '.join(names[:2])}。"
        else:
            prefix = "长按会先试手机热点，但还没有保存热点档案。"
    else:
        prefix = "长按开电台时不会自动切热点。"
    if ip:
        return f"{prefix} 当前网络在线，IP {ip}。"
    return f"{prefix} 当前还没拿到 IP；如果要出门，先打开手机热点再长按橙色键。"


