def publish_ambient_observation():
    save_ambient_mode("scan_once")
    report = observe_once(capture=True)
    message = ambient_summary(report)
    publish_state(
        status="idle",
        label="静音中" if MUTE else "Ambient DJ",
        city="环境观察",
        track="Sunset Radio",
        message=f"静音中：{message}" if MUTE else message,
    )
    # 「在外面问家里」的回执：扫描结果同时写进信箱（kind=scan），手机端即刻可读。
    # 仍是手动触发的一帧观察，画面用完即删——只有文字描述离开这台机器。
    if PET_ENABLED:
        try:
            now_ts = pet_now_ts()
            tz = pet_tz()
            post_json(
                "/api/pi-inbox",
                {
                    "letter": {
                        "kind": "scan",
                        "at": f"{pet_state.local_date_str(now_ts, tz)}T{pet_state.local_clock_str(now_ts, tz)}",
                        "city": "家",
                        "body": message,
                        "source": "scan",
                    }
                },
            )
        except Exception:
            pass


