def compact_text(value, limit=18):
    text = str(value or "")
    return text if len(text) <= limit else f"{text[:limit - 3]}..."


def current_city():
    slug = current_city_slug()
    if not slug:
        return None
    return next((city for city in catalog if city.get("slug") == slug), None)


def city_display_name(city):
    return str((city or {}).get("cityNameZh") or (city or {}).get("nameZh") or (city or {}).get("cityName") or (city or {}).get("slug") or "这座城市")


def publish_city_tracks(city):
    if not city:
        message = "先说一座城市，音乐DJ 再展开歌单。"
        publish_state(
            status="idle",
            label="静音中" if MUTE else "DJ",
            city="城市歌单",
            track="Sunset Radio",
            message=f"静音中：{message}" if MUTE else message,
        )
        speak_text(message)
        return
    tracks = city.get("tracks") or []
    titles = " / ".join(compact_text(track.get("title")) for track in tracks[:3])
    name = city_display_name(city)
    message = f"{name}有{len(tracks)}首：{titles}。" if titles else f"{name}暂时还没有可播放歌曲。"
    publish_state(
        status="idle",
        label="静音中" if MUTE else "City songs",
        city="城市歌单",
        track=name,
        message=f"静音中：{message}" if MUTE else message,
    )
    speak_text(message)


def publish_current_city_tracks():
    publish_city_tracks(current_city())


def publish_city_story(city):
    if not city:
        message = "先说一座城市，音乐DJ 再讲它的黄昏。"
        publish_state(
            status="idle",
            label="静音中" if MUTE else "DJ",
            city="城市故事",
            track="Sunset Radio",
            message=f"静音中：{message}" if MUTE else message,
        )
        speak_text(message)
        return
    name = city_display_name(city)
    desc = compact_text(re.sub(r"\s+", " ", city.get("description") or "").strip(), 52)
    tracks = city.get("tracks") or []
    titles = " / ".join(compact_text(track.get("title")) for track in tracks[:2])
    if desc and titles:
        message = f"{name}：{desc}。这里先接 {titles}。"
    elif desc:
        message = f"{name}：{desc}。"
    elif titles:
        message = f"{name}在日落电台有{len(tracks)}首歌，先从 {titles} 听起。"
    else:
        message = f"{name}还在等一段适合它的黄昏。"
    publish_state(
        status="idle",
        label="静音中" if MUTE else "City story",
        city="城市故事",
        track=name,
        message=f"静音中：{message}" if MUTE else message,
    )
    speak_text(message)


