def handle_command(text, source=""):
    text = (text or "").strip()
    if not text:
        return
    wake_tail = strip_wake_word(text)
    if wake_tail is not None:
        woke = publish_wake(text)
        if wake_tail and woke:
            handle_command(wake_tail, source=source)
        return
    quiet_intent = strip_leading_quiet_command(text)
    if quiet_intent and quiet_intent != text and (
        LAST_HEARD_RE.search(quiet_intent) or VOICE_CORRECTION_RE.search(quiet_intent)
    ):
        if handle_quiet_prefixed_query(text):
            return
    if LAST_HEARD_RE.search(text):
        if TEXT_ONLY_RE.search(text):
            run_without_speech(publish_last_heard)
            return
        publish_last_heard()
        return
    if VOICE_CORRECTION_RE.search(text):
        if TEXT_ONLY_RE.search(text):
            run_without_speech(publish_voice_correction)
            return
        publish_voice_correction()
        return
    remember_voice_text(text, source=source)
    if handle_quiet_prefixed_query(text):
        return
    # 电子宠物：任何语音/按键互动都是陪伴（亲密度）；宠物意图放在梯子最前，
    # 免得「它去哪了」被后面的电台路线问句接走。
    if PET_ENABLED and source in {"voice", "button"}:
        try:
            pet_note_interaction(source)
        except Exception:
            pass
    if PET_ENABLED and not PET_SONG_CONTEXT_RE.search(text):
        # 歌曲语境守卫：句子一旦提到歌/曲/播放，即便含「它/摸摸」也交给电台梯子处理。
        if FORM_DEMO_RE.search(text):
            publish_form_demo()
            return
        if not PET_FORM_BLOCK_RE.search(text):
            if PET_FORM_CYCLE_RE.search(text):
                publish_pet_form_cycle()
                return
            if PET_FORM_TURNTABLE_RE.search(text):
                publish_pet_form("turntable")
                return
            if PET_FORM_FACE_RE.search(text):
                publish_pet_form("face")
                return
            if PET_FORM_AVATAR_RE.search(text):
                publish_pet_form("avatar")
                return
        if PET_TOUCH_RE.search(text):
            publish_pet_touch()
            return
        if PET_DRIFT_RE.search(text):
            publish_pet_drift_now()
            return
        if PET_HOME_RE.search(text):
            publish_pet_home_now()
            return
        if PET_WHERE_RE.search(text):
            publish_pet_where()
            return
        if PET_STATUS_RE.search(text):
            publish_pet_status()
            return
    if HARD_MUTE_RE.search(text):
        publish_audio_mode("hard_mute", reason="user hard mute", message="硬静音：我会只在屏幕上响应，不出声。")
        return
    if WAKE_NAME_QUESTION_RE.search(text):
        publish_voice_doctor()
        return
    if UNMUTE_DIALOG_RE.search(text):
        publish_audio_mode(
            "dialog",
            reason="user dialog unmute",
            ttl=AUDIO_DIALOG_TTL_SEC,
            message="对话待命：我可以短暂回应，但不会自动放歌。",
        )
        speak_text("我在。")
        return
    if is_hotspot_portable_advice_question(text):
        if TEXT_ONLY_RE.search(text):
            run_without_speech(publish_portable_briefing)
            return
        publish_portable_briefing()
        return
    if LOCAL_CONTROL_RE.search(text):
        run_without_speech(publish_local_control_policy)
        return
    if HOTSPOT_CONNECT_SAFETY_RE.search(text):
        if TEXT_ONLY_RE.search(text):
            run_without_speech(publish_hotspot_connect_safety)
            return
        publish_hotspot_connect_safety()
        return
    if HOTSPOT_CONNECT_NEGATIVE_RE.search(text):
        if is_hotspot_status_question(text):
            if TEXT_ONLY_RE.search(text):
                run_without_speech(publish_hotspot_status)
                return
            publish_hotspot_status()
            return
        if is_hotspot_portable_advice_question(text):
            if TEXT_ONLY_RE.search(text):
                run_without_speech(publish_portable_briefing)
                return
            publish_portable_briefing()
            return
        if HOTSPOT_CONNECT_SAFETY_RE.search(text):
            if TEXT_ONLY_RE.search(text):
                run_without_speech(publish_hotspot_connect_safety)
                return
            publish_hotspot_connect_safety()
            return
        publish_hotspot_connect_blocked()
        return
    if (
        HOTSPOT_CONNECT_RE.search(text)
        and not HOTSPOT_QUESTION_RE.search(text)
        and not HOTSPOT_LOW_POWER_FALSE_POSITIVE_RE.search(text)
    ):
        if TEXT_ONLY_RE.search(text):
            run_without_speech(publish_hotspot_connect)
            return
        publish_hotspot_connect()
        return
    if AMBIENT_PRIVACY_RE.search(text):
        publish_ambient_privacy()
        return
    if CONTEXT_MEMORY_RE.search(text):
        publish_context_memory()
        return
    if SKILL_FALLBACK_RE.search(text):
        publish_skill_fallback_overview()
        return
    if NEGATIVE_PLAYBACK_ACTION_RE.search(text) and PREV_TRACK_QUERY_RE.search(text):
        publish_previous_track()
        return
    if NEGATIVE_PLAYBACK_ACTION_RE.search(text) and NEXT_TRACK_QUERY_RE.search(text):
        publish_current_city_tracks()
        return
    if NEGATIVE_PLAYBACK_ACTION_RE.search(text) and (
        SONG_CITY_RELATION_RE.search(text)
        or (SONG_PLACE_FIT_RE.search(text) and (PLACE_RELATION_TARGET_RE.search(text) or match_city(text)))
        or SONG_MEANING_RE.search(text)
        or STORY_RE.search(text)
    ):
        publish_current_track_story()
        return
    if NEGATIVE_PLAYBACK_ACTION_RE.search(text) and NOW_RE.search(text):
        publish_current_track()
        return
    if NEGATIVE_PLAYBACK_ACTION_RE.search(text):
        publish_playback_action_blocked()
        return
    if RADIO_SOUND_RE.search(text):
        if START_PLAY_RE.search(text) and not match_city(text):
            start_radio_playback("user start playback")
            return
        publish_audio_mode(
            "radio",
            reason="user enabled radio sound",
            ttl=AUDIO_RADIO_TTL_SEC,
            message="电台声音已打开；现在明确点歌或切城时可以播放。",
        )
        speak_text("电台声音已打开。")
        return
    if GREETING_RE.search(text):
        publish_state(
            status="listening",
            label="对话待命",
            city="音乐DJ",
            track="对话待命",
            message="我在。你可以说切歌、听柏林，或长按橙色键先找热点再开关电台。",
        )
        speak_text("我在。")
        return
    if TOGGLE_AUDIO_RE.search(text):
        toggle_audio_from_button()
        return
