def maybe_auto_advance():
    if player and player.poll() is not None and playlist:
        play_next(1)


def publish_heartbeat():
    state = fetch_json("/api/pi-state").get("state", {})
    if int(state.get("pending") or 0) == 0:
        if MUTE and not is_silent_label(state.get("label")):
            publish_state(
                status="idle",
                label="静音中",
                city="音乐DJ",
                track="安静待命",
                message=f"音乐DJ 已静音，载入 {len(catalog)} 座城市。",
                _remember=False,
            )
        return
    publish_state(
        status=state.get("status") or "queued",
        label=state.get("label") or "Command queued",
        message=state.get("message") or "音乐DJ 收到。",
        _remember=False,
    )


def main():
    global catalog
    catalog = load_catalog()
    publish_state(
        status="idle",
        label="静音中" if MUTE else "Native radio",
        city="音乐DJ" if MUTE else "Sunset Radio",
        track="安静待命" if MUTE else "",
        message=f"音乐DJ 已静音，载入 {len(catalog)} 座城市。" if MUTE else f"音乐DJ 已载入 {len(catalog)} 座城市。",
    )
    last_heartbeat = 0
    last_pet_tick = 0.0
    while True:
        try:
            maybe_auto_advance()
            commands = []
            commands.extend(claim_commands(0, "smoke"))
            commands.extend(claim_commands(BUTTON_CLAIM_AFTER_MS, "button"))
            commands.extend(claim_commands(VOICE_CLAIM_AFTER_MS, "voice"))
            commands.extend(claim_commands(CLAIM_AFTER_MS))
            for command in commands:
                handle_command(command.get("text") or "", source=command.get("source") or "")
            if time.monotonic() - last_heartbeat > 12:
                publish_heartbeat()
                last_heartbeat = time.monotonic()
            # 宠物心跳：低频自主行为（眨眼犯困想你、黄昏神游），异常绝不拖垮命令主循环。
            if PET_ENABLED and time.monotonic() - last_pet_tick > PET_TICK_SEC:
                try:
                    pet_tick_cycle()
                except Exception:
                    pass
                last_pet_tick = time.monotonic()
        except (urllib.error.URLError, TimeoutError, json.JSONDecodeError, OSError):
            pass
        time.sleep(POLL_SEC)


if __name__ == "__main__":
    main()
